"""Declarative mixins shared by product tables."""

from __future__ import annotations

from datetime import UTC, datetime
from uuid import UUID, uuid4

from sqlalchemy import DateTime, Uuid
from sqlalchemy.orm import Mapped, mapped_column


def utcnow() -> datetime:
    return datetime.now(UTC)


def as_utc(value: datetime) -> datetime:
    """Normalize a stored timestamp; some drivers return naive UTC values."""
    return value if value.tzinfo is not None else value.replace(tzinfo=UTC)


class UuidPrimaryKeyMixin:
    """UUID primary key generated by the application and by ``gen_random_uuid()``."""

    id: Mapped[UUID] = mapped_column(Uuid, primary_key=True, default=uuid4)


class TimestampMixin:
    """``created_at``/``updated_at`` pair; migrations add the database-side trigger."""

    created_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, default=utcnow
    )
    updated_at: Mapped[datetime] = mapped_column(
        DateTime(timezone=True), nullable=False, default=utcnow, onupdate=utcnow
    )
